package network.tos.blockchain.ton.contract

import org.ton.boc.BagOfCells
import org.ton.cell.Cell
import org.ton.block.AddrStd

/** Source-pinned TOS SDK FunC reference family, not an RPC-selected code hash.
 * Source: tosnetwork/tos@bb2b07a40d838940bc16efa6cf72d24bc343c148
 * sdk/js/packages/contracts/src/token/codes.ts. Native Tol constants are compiled from the same pinned source.
 */
object TokenContractCodes {
    val referenceMaster: Cell by lazy { decode("") }
    val referenceWallet: Cell by lazy { decode("") }
    val nativeMaster: Cell by lazy { decode("") }
    val nativeWallet: Cell by lazy { decode("") }
    class Family internal constructor(val name: String, val master: Cell, val wallet: Cell)
    private val supported by lazy { listOf(Family("native-tol-v1", nativeMaster, nativeWallet), Family("sdk-func-v1", referenceMaster, referenceWallet)) }
    fun family(owner: AddrStd, master: AddrStd, wallet: AddrStd): Family = supported.singleOrNull {
        TokenWalletState.address(owner, master, it.wallet) == wallet
    } ?: throw IllegalArgumentException("Unsupported Token wallet code family")
    private fun decode(encoded: String): Cell = BagOfCells(encoded.chunked(2).map { it.toInt(16).toByte() }.toByteArray()).roots.single()
}
